const header=document.querySelector('.site-header');const menuBtn=document.querySelector('.menu-toggle');const mobileMenu=document.querySelector('.mobile-menu');
addEventListener('scroll',()=>header.classList.toggle('scrolled',scrollY>24),{passive:true});
menuBtn.addEventListener('click',()=>{const open=menuBtn.getAttribute('aria-expanded')==='true';menuBtn.setAttribute('aria-expanded',String(!open));menuBtn.setAttribute('aria-label',open?'Open menu':'Close menu');menuBtn.classList.toggle('active',!open);mobileMenu.classList.toggle('open',!open)});
mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menuBtn.setAttribute('aria-expanded','false');menuBtn.setAttribute('aria-label','Open menu');menuBtn.classList.remove('active');mobileMenu.classList.remove('open')}));
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1,rootMargin:'0px 0px -30px'});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const moreBtn=document.querySelector('.more-services>button');const moreList=document.querySelector('#more-list');moreBtn.addEventListener('click',()=>{const open=moreBtn.getAttribute('aria-expanded')==='true';moreBtn.setAttribute('aria-expanded',String(!open));moreBtn.querySelector('span').textContent=open?'+':'−';moreList.hidden=open});
document.querySelectorAll('[data-wa-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const name=data.get('name')||'';const service=data.get('service')||'';const message=data.get('message')||'';const location=data.get('location');let text=`Hello Blue-Amaya Developments,\n\nMy name is ${name}.\n\nI'm interested in:\n${service}\n`;if(location)text+=`\nProject location:\n${location}\n`;text+=`\nMessage:\n${message}\n\nPlease assist me with a quotation.`;window.open(`https://wa.me/263790012094?text=${encodeURIComponent(text)}`,'_blank','noopener')}));
const filterButtons=[...document.querySelectorAll('.filters button')];const galleryItems=[...document.querySelectorAll('.gallery-item')];filterButtons.forEach(btn=>btn.addEventListener('click',()=>{filterButtons.forEach(b=>b.classList.remove('active'));btn.classList.add('active');const filter=btn.dataset.filter;galleryItems.forEach((item,i)=>{const show=filter==='all'||item.dataset.cat.split(' ').includes(filter);item.hidden=!show;if(show){item.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'none'}],{duration:420,delay:i*25,easing:'cubic-bezier(.22,1,.36,1)'})}})}));
const lightbox=document.querySelector('.lightbox');const lbImg=lightbox.querySelector('img');const lbCaption=lightbox.querySelector('figcaption');let current=0;function visibleItems(){return galleryItems.filter(i=>!i.hidden)}function showItem(index){const items=visibleItems();current=(index+items.length)%items.length;const item=items[current];lbImg.src=item.dataset.src;lbImg.alt=item.querySelector('img').alt;lbCaption.textContent=item.dataset.title;lightbox.hidden=false;document.body.style.overflow='hidden';lightbox.querySelector('.lightbox-close').focus()}galleryItems.forEach(item=>item.addEventListener('click',()=>showItem(visibleItems().indexOf(item))));function closeLightbox(){lightbox.hidden=true;document.body.style.overflow=''}lightbox.querySelector('.lightbox-close').addEventListener('click',closeLightbox);lightbox.querySelector('.lightbox-prev').addEventListener('click',()=>showItem(current-1));lightbox.querySelector('.lightbox-next').addEventListener('click',()=>showItem(current+1));lightbox.addEventListener('click',e=>{if(e.target===lightbox)closeLightbox()});addEventListener('keydown',e=>{if(lightbox.hidden)return;if(e.key==='Escape')closeLightbox();if(e.key==='ArrowLeft')showItem(current-1);if(e.key==='ArrowRight')showItem(current+1)});
